ALTER TABLE public.user_settings ADD COLUMN push_enabled boolean NOT NULL DEFAULT false;
CREATE TABLE public.push_subscriptions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL DEFAULT auth.uid(), endpoint text NOT NULL, keys jsonb NOT NULL, timezone text NOT NULL DEFAULT 'UTC', created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id,endpoint));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.push_subscriptions TO authenticated;
GRANT ALL ON public.push_subscriptions TO service_role;
ALTER TABLE public.push_subscriptions ENABLE ROW LEVEL SECURITY;
CREATE POLICY own ON public.push_subscriptions FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE TABLE public.push_focus_deadlines (user_id uuid NOT NULL DEFAULT auth.uid(), session_id uuid NOT NULL, end_at timestamptz NOT NULL, PRIMARY KEY(user_id,session_id));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.push_focus_deadlines TO authenticated;
GRANT ALL ON public.push_focus_deadlines TO service_role;
ALTER TABLE public.push_focus_deadlines ENABLE ROW LEVEL SECURITY;
CREATE POLICY own ON public.push_focus_deadlines FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE TABLE public.push_presence (user_id uuid PRIMARY KEY DEFAULT auth.uid(), alive_until timestamptz NOT NULL);
GRANT SELECT,INSERT,UPDATE,DELETE ON public.push_presence TO authenticated;
GRANT ALL ON public.push_presence TO service_role;
ALTER TABLE public.push_presence ENABLE ROW LEVEL SECURITY;
CREATE POLICY own ON public.push_presence FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE TABLE public.reminder_claims (user_id uuid NOT NULL DEFAULT auth.uid(), reminder_key text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(user_id,reminder_key));
GRANT SELECT,DELETE ON public.reminder_claims TO authenticated;
GRANT ALL ON public.reminder_claims TO service_role;
ALTER TABLE public.reminder_claims ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_read ON public.reminder_claims FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE POLICY own_delete ON public.reminder_claims FOR DELETE TO authenticated USING(user_id=auth.uid());
CREATE OR REPLACE FUNCTION public.claim_reminder(_key text) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL OR length(_key)>500 THEN RETURN false; END IF; INSERT INTO public.reminder_claims(user_id,reminder_key) VALUES(auth.uid(),_key) ON CONFLICT DO NOTHING; RETURN FOUND; END $$;
REVOKE ALL ON FUNCTION public.claim_reminder(text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.claim_reminder(text) TO authenticated;
CREATE INDEX push_subscriptions_user ON public.push_subscriptions(user_id);
CREATE INDEX push_focus_due ON public.push_focus_deadlines(end_at);